// Catálogo dos efeitos do pixelfx usados na mesa (gerado a partir do `meta` de cada efeito).
// Ficaram de fora os que desenham um boneco (feitos para golpes) e categorias fora do tema.

export type FxCat = 'fire' | 'ice' | 'lightning' | 'arcane' | 'holy' | 'shadow' | 'nature' | 'water' | 'weather' | 'explosions' | 'impacts' | 'spawn' | 'pickups' | 'critters';

export interface FxInfo {
  id: string;
  nome: string;
  cat: FxCat;
  /** Repete sozinho (fogueira, chuva…). Os demais tocam uma vez. */
  loop: boolean;
  /** Duração de um ciclo, em segundos. */
  dur: number;
  /** Tamanho do quadro em pixels de pixel art e o ponto de apoio (pé do efeito). */
  w: number;
  h: number;
  ox: number;
  oy: number;
  /** Tem chão próprio redesenhado nas duas perspectivas (isométrica e reta). */
  persp?: boolean;
}

